import{_ as e,c as t,o as n,ag as s}from"./chunks/framework.CQuhCYrb.js";const h=JSON.parse('{"title":"Dataminr (Research Tool)","description":"","frontmatter":{"title":"Dataminr (Research Tool)"},"headers":[],"relativePath":"research/dataminr-research-tool.md","filePath":"research/dataminr-research-tool.md","lastUpdated":null}'),i={name:"research/dataminr-research-tool.md"};function r(o,a,l,d,p,m){return n(),t("div",null,[...a[0]||(a[0]=[s(`<h1 id="dataminr-research-tool" tabindex="-1">Dataminr (Research Tool) <a class="header-anchor" href="#dataminr-research-tool" aria-label="Permalink to &quot;Dataminr (Research Tool)&quot;">​</a></h1><h2 id="first-alert-dataminr" tabindex="-1">First Alert - Dataminr <a class="header-anchor" href="#first-alert-dataminr" aria-label="Permalink to &quot;First Alert - Dataminr&quot;">​</a></h2><p>A step-by-step guide to getting yourself an account.</p><h3 id="dataminr-account-requirements" tabindex="-1">Dataminr Account Requirements <a class="header-anchor" href="#dataminr-account-requirements" aria-label="Permalink to &quot;Dataminr Account Requirements&quot;">​</a></h3><ol><li><p>.mil account</p></li><li><p><em>[User Form]</em> (in email)</p></li></ol><h3 id="steps" tabindex="-1">Steps <a class="header-anchor" href="#steps" aria-label="Permalink to &quot;Steps&quot;">​</a></h3><h3 id="email-dataminr" tabindex="-1">Email Dataminr <a class="header-anchor" href="#email-dataminr" aria-label="Permalink to &quot;Email Dataminr&quot;">​</a></h3><p>Email Amelia Wald:</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>awald@dataminr.com</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Amelia,</span></span>
<span class="line"><span></span></span>
<span class="line"><span>I am requesting a Dataminr account. I will be CC&#39;ing you as I request an account through sarmy.pentagon.hqda.mbx.pai-operations-group@mail.mil.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Respectfully,</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><p>By sending a WARNO email, Amelia can have the account ready sooner.</p><h3 id="email-army-about-dataminr" tabindex="-1">Email Army about Dataminr <a class="header-anchor" href="#email-army-about-dataminr" aria-label="Permalink to &quot;Email Army about Dataminr&quot;">​</a></h3><p>Email Army PAI:</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>sarmy.pentagon.hqda.mbx.pai-operations-group@mail.mil; gary.l.williams56.ctr@army.mil</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>CC:</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>awald@dataminr.com</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>Email Template:</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Dear PAI Operations Group,</span></span>
<span class="line"><span></span></span>
<span class="line"><span>I am requesting an account for Dataminr to support our Situational Awareness efforts. I have attached the filled-out PAI User Agreement with all my relevant information to facilitate the process.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Additionally, I am CC&#39;ing the Dataminr representative on this email to ensure a smooth and efficient account setup process.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Thank you for your prompt attention to this matter.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Best regards,</span></span>
<span class="line"><span>[Name](Your)</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br></div></div><p><em>You should get a response within 48 hours with approval.</em></p><h4 id="pai-user-form" tabindex="-1">PAI User Form <a class="header-anchor" href="#pai-user-form" aria-label="Permalink to &quot;PAI User Form&quot;">​</a></h4><p>PAI User Form is a spreadsheet with the following information:</p><p>You can copy over the headers to a spreadsheet or to the email directly and fill this in.</p><p><strong>PAI User Form Information:</strong></p><table tabindex="0"><thead><tr><th>First Name</th><th>Last Name</th><th>Rank</th><th>Unit</th><th>Position</th><th>Email</th><th>Common Profile</th><th>AOR</th><th>Desktop/Mobile</th><th>Country 1</th><th>Country 2</th><th>Country 3</th><th>Base</th></tr></thead><tbody><tr><td>John</td><td>Doe</td><td>CPT</td><td>123rd Infantry</td><td>Operations Officer</td><td>john.doe@army.mil</td><td>Operations Center</td><td>Global</td><td>Desktop and Mobile</td><td>SOUTHCOM</td><td>PACOM</td><td>EUCOM</td><td>Fort Liberty</td></tr><tr><td>John</td><td>Doe</td><td>SSG</td><td>123 Logistics</td><td>Logistics NCO</td><td>john.doe@army.mil</td><td>Force Protection</td><td>PACOM</td><td>Desktop Only</td><td>CENTCOM</td><td>AFRICOM</td><td>N/A</td><td>Camp Ari</td></tr><tr><td>John</td><td>Doe</td><td>MAJ</td><td>123 Engineers</td><td>Engineer Officer</td><td>john.doe@army.mil</td><td>Situational Awareness</td><td>SOUTHCOM</td><td>Desktop and Mobile</td><td>NORTHCOM</td><td>EUCOM</td><td>N/A</td><td>Fort XYZ</td></tr></tbody></table><h5 id="pai-user-form-notes" tabindex="-1">PAI User Form Notes <a class="header-anchor" href="#pai-user-form-notes" aria-label="Permalink to &quot;PAI User Form Notes&quot;">​</a></h5><h2 id="the-information-provided-under-the-army-account-information-is-maintained-by-damo-cyf-for-account-management-and-is-not-shared-outside-of-the-army" tabindex="-1">The information provided under the <em>Army Account Information</em> is maintained by DAMO-CYF for account management and is not shared outside of the Army. <a class="header-anchor" href="#the-information-provided-under-the-army-account-information-is-maintained-by-damo-cyf-for-account-management-and-is-not-shared-outside-of-the-army" aria-label="Permalink to &quot;The information provided under the *Army Account Information* is maintained by DAMO-CYF for account management and is not shared outside of the Army.&quot;">​</a></h2><h2 id="under-minimum-profile-information-the-four-essential-elements-required-to-create-an-account-include-email-common-profile-aor-and-type-of-application-these-details-can-be-updated-anytime" tabindex="-1">Under <em>Minimum Profile Information</em>, the four essential elements required to create an account include Email, Common Profile, AOR, and type of application. These details can be updated anytime. <a class="header-anchor" href="#under-minimum-profile-information-the-four-essential-elements-required-to-create-an-account-include-email-common-profile-aor-and-type-of-application-these-details-can-be-updated-anytime" aria-label="Permalink to &quot;Under *Minimum Profile Information*, the four essential elements required to create an account include Email, Common Profile, AOR, and type of application. These details can be updated anytime.&quot;">​</a></h2><ol><li><p><em>Common Profile</em> refers to the category that best describes the role/mission, such as Leadership, Operations Center, Situational Awareness, Force Protection, or Information Environment.</p></li><li><p><em>AOR</em> refers to the Area of Responsibility the user is interested in.</p></li><li><p><em>Desktop/Mobile</em>: Choose between &quot;Desktop Only&quot; or &quot;Desktop and Mobile&quot; options. The mobile app is available for iOS and Android and is DISA-approved for personal and government-owned devices.</p></li><li><p><em>Additional Profile Information</em> is optional and can be modified anytime via the dashboard. This includes geographic areas like country, state, and base/facility.</p></li></ol><p>[Awareness]</p>`,29)])])}const u=e(i,[["render",r]]);export{h as __pageData,u as default};
